const PARTS = {
  fuelTank:{ cat:"power", color:"#e5a934", modes:["diesel"], explode:[0,-2.2,0], anchor:[0,0.45,1.3],
    fr:{ name:"Réservoir de gazole", desc:"Sous le châssis, entre les bogies: 5 000 à 18 000 L de gazole, soit jusqu'à 15 tonnes. Une pompe l'envoie sous pression aux injecteurs. Autonomie: un à deux jours de service. C'est la seule réserve d'énergie à bord: tout le reste ne fait que la transformer." },
    en:{ name:"Fuel tank", desc:"Under the frame, between the bogies: 5,000 to 18,000 L of diesel, up to 15 tonnes. A pump feeds it under pressure to the injectors. Range: one to two days of service. It is the only energy store on board; everything else just converts it." } },
  engine:{ cat:"power", color:"#5b8db3", modes:["diesel"], explode:[0,1.4,0], anchor:[-0.7,3.9,0],
    fr:{ name:"Moteur diesel (moteur primaire)", desc:"Un V8 à V16 lent: 100 à 250 litres de cylindrée, 270 tr/min au ralenti, 900 à 1 050 tr/min à pleine charge, 2 000 à 3 300 kW. Le gazole injecté s'enflamme sous la compression et pousse les pistons, qui font tourner le vilebrequin. Point clé: il n'est relié à aucune roue. Il ne fait tourner que l'alternateur. Une locomotive diesel-électrique est une centrale électrique sur rails." },
    en:{ name:"Diesel engine (prime mover)", desc:"A slow V8 to V16: 100 to 250 litres of displacement, 270 rpm at idle, 900 to 1,050 rpm at full load, 2,000 to 3,300 kW. Injected fuel ignites under compression and pushes the pistons, which turn the crankshaft. Key point: it is not connected to any wheel. It only turns the alternator. A diesel-electric locomotive is a power plant on rails." } },
  turbo:{ cat:"power", color:"#9aa5b1", modes:["diesel"], explode:[0,2.6,0], anchor:[-3.1,4.0,0.5],
    fr:{ name:"Turbocompresseur", desc:"Les gaz d'échappement font tourner une turbine à 20 000 tr/min, qui entraîne un compresseur: l'air d'admission est comprimé, chaque cylindre reçoit plus d'oxygène, donc brûle plus de gazole. Gain: environ 50 % de puissance pour le même moteur. Au démarrage, il faut quelques secondes pour qu'il monte en régime (le fameux temps de réponse turbo)." },
    en:{ name:"Turbocharger", desc:"Exhaust gas spins a turbine at 20,000 rpm which drives a compressor: intake air is packed into the cylinders, so each one gets more oxygen and burns more fuel. Gain: about 50% more power from the same engine. On start-up it needs a few seconds to spool up (turbo lag)." } },
  exhaust:{ cat:"power", color:"#6f7a86", modes:["diesel"], explode:[0,3.4,0], anchor:[-3.1,4.9,0],
    fr:{ name:"Échappement", desc:"Silencieux et cheminée de toit. Les gaz sortent à 400 à 500 °C après avoir traversé la turbine. La fumée noire au démarrage vient du gazole mal brûlé tant que le turbo ne fournit pas assez d'air." },
    en:{ name:"Exhaust stack", desc:"Silencer and roof stack. Gas leaves at 400 to 500 °C after passing through the turbine. The black smoke on start-up is unburnt fuel while the turbo is not yet supplying enough air." } },
  alternator:{ cat:"power", color:"#c77b3a", modes:["diesel"], explode:[0,1.2,2.3], anchor:[3.4,3.7,0],
    fr:{ name:"Alternateur principal", desc:"Boulonné directement sur le vilebrequin, il tourne à la vitesse du moteur. Son rotor aimanté (excité par un courant réglable) induit dans les bobinages du stator un courant alternatif triphasé de 600 à 1 400 V. La tension dépend du régime ET de l'excitation: au ralenti sans excitation, il tourne pour rien et ne débite aucun courant. C'est l'excitation, pas la manette directement, qui dose la puissance envoyée aux roues." },
    en:{ name:"Main alternator", desc:"Bolted directly to the crankshaft, it spins at engine speed. Its rotor (excited by an adjustable field current) induces a three-phase AC of 600 to 1,400 V in the stator windings. Voltage depends on speed AND excitation: at idle with no excitation it spins for nothing and delivers no current. Excitation, not the throttle itself, meters the power sent to the wheels." } },
  rectifier:{ cat:"conv", color:"#3cc8ea", modes:["diesel"], explode:[0,2.4,0], anchor:[5.0,4.0,0],
    fr:{ name:"Redresseur", desc:"Pont de diodes de puissance: transforme le courant alternatif de l'alternateur en courant continu sur le bus DC (1 000 à 1 800 V). Pas de pièce mobile, refroidi par air." },
    en:{ name:"Rectifier", desc:"Power diode bridge: turns the alternator's AC into DC on the DC link (1,000 to 1,800 V). No moving parts, air cooled." } },
  converter4q:{ cat:"conv", color:"#3cc8ea", modes:["electric","tgv"], explode:[0,2.4,0], anchor:[5.0,4.0,0],
    fr:{ name:"Convertisseur 4 quadrants", desc:"Redresseur actif à transistors IGBT: transforme le courant alternatif d'un secondaire du transformateur en courant continu sur le bus DC (2 800 V typiquement) et maintient une tension stable. Il fonctionne dans les deux sens: en freinage, il renvoie l'énergie des moteurs vers la caténaire." },
    en:{ name:"Four-quadrant converter", desc:"Active IGBT rectifier: turns the AC from a transformer secondary into DC on the DC link (typically 2,800 V) and holds it steady. It works both ways: when braking, it pushes the motors' energy back into the overhead line." } },
  inverters:{ cat:"conv", color:"#c084ff", modes:["diesel","electric","tgv"], explode:[0,1.2,2.5], anchor:[6.0,4.0,0.9],
    fr:{ name:"Onduleurs de traction", desc:"Un par bogie. Des transistors IGBT hachent le courant continu pour recréer un courant triphasé de fréquence et de tension variables (0 à 120 Hz). C'est cette fréquence qui fixe la vitesse des moteurs asynchrones, et la tension qui fixe le couple. Refroidis à l'eau ou à l'air forcé." },
    en:{ name:"Traction inverters", desc:"One per bogie. IGBT transistors chop the DC to recreate a three-phase current of variable frequency and voltage (0 to 120 Hz). That frequency sets the speed of the induction motors, and the voltage sets the torque. Water or forced-air cooled." } },
  control:{ cat:"conv", color:"#e7ecf1", modes:["diesel","electric","tgv"], explode:[0,3.2,0], anchor:[5.6,4.0,-0.9],
    fr:{ name:"Calculateur de traction", desc:"L'ordinateur de bord lit la manette, la vitesse et le glissement de chaque essieu. Il dose le régime du moteur diesel ou la consigne des convertisseurs, l'excitation, la fréquence des onduleurs, et détecte le patinage roue-rail pour réduire l'effort. Alimenté par la batterie 74 V." },
    en:{ name:"Traction control computer", desc:"The on-board computer reads the throttle, the speed and the slip of each axle. It sets engine speed or converter setpoints, excitation, inverter frequency, and detects wheel slip to reduce effort. Powered by the 74 V battery." } },
  motors:{ cat:"traction", color:"#c084ff", modes:["diesel","electric","tgv"], explode:[0,0,2.6], anchor:[6.0,1.2,1.4],
    fr:{ name:"Moteurs de traction (×4)", desc:"Un moteur asynchrone triphasé par essieu, 500 à 1 000 kW chacun, suspendu dans le bogie. Un pignon sur l'arbre entraîne la grande couronne fixée sur l'essieu (rapport de 3 à 4 pour 1): le moteur tourne vite, la roue tourne lentement avec beaucoup de couple. Ils sont réversibles: en freinage, entraînés par les roues, ils deviennent des générateurs." },
    en:{ name:"Traction motors (×4)", desc:"One three-phase induction motor per axle, 500 to 1,000 kW each, hung in the bogie. A pinion on the shaft drives the large gear fixed on the axle (ratio 3 to 4 to 1): the motor spins fast, the wheel turns slowly with lots of torque. They are reversible: when braking, driven by the wheels, they become generators." } },
  bogies:{ cat:"traction", color:"#5a6068", modes:["diesel","electric","tgv"], explode:[0,0,0], anchor:[-6.0,1.2,1.4],
    fr:{ name:"Bogies et essieux", desc:"Deux châssis pivotants portant chacun deux essieux, la suspension et les moteurs. Les roues en acier de 1 à 1,25 m de diamètre transmettent l'effort par simple adhérence roue-rail. C'est elle qui limite l'effort au démarrage (environ 300 à 400 kN pour 4 essieux): au-delà, ça patine. Les freins mécaniques (disques ou sabots) sont aussi ici." },
    en:{ name:"Bogies and axles", desc:"Two pivoting frames, each carrying two axles, the suspension and the motors. Steel wheels of 1 to 1.25 m diameter transmit effort through plain wheel-rail adhesion. Adhesion limits starting effort (about 300 to 400 kN for 4 axles): beyond that, the wheels slip. The mechanical brakes (discs or shoes) live here too." } },
  brakeGrids:{ cat:"traction", color:"#ff7f3f", modes:["diesel"], explode:[0,3.6,0], anchor:[3.4,4.8,0],
    fr:{ name:"Résistances de freinage", desc:"Freinage rhéostatique: manette à zéro, les moteurs sont entraînés par les roues et produisent du courant. Il est envoyé dans ces grilles résistives sur le toit, qui chauffent au rouge et sont refroidies par un ventilateur. Le train ralentit sans user les freins mécaniques. En descente, c'est le frein principal." },
    en:{ name:"Dynamic brake grids", desc:"Rheostatic braking: throttle at zero, the motors are driven by the wheels and generate current. It is dumped into these roof resistor grids, which glow red and are cooled by a fan. The train slows without wearing the mechanical brakes. On long downgrades this is the main brake." } },
  roofResistors:{ cat:"traction", color:"#ff7f3f", modes:["electric","tgv"], explode:[0,3.6,0], anchor:[-2.5,4.8,0],
    fr:{ name:"Résistances de freinage", desc:"En freinage, l'énergie des moteurs repart en priorité vers la caténaire (récupération). Si la ligne ne peut pas l'absorber, elle est dissipée en chaleur dans ces résistances de toit: c'est le freinage rhéostatique de secours." },
    en:{ name:"Braking resistors", desc:"When braking, the motors' energy goes first back into the overhead line (regeneration). If the line cannot absorb it, it is dumped as heat in these roof resistors: rheostatic braking as a fallback." } },
  radiator:{ cat:"aux", color:"#ff5f45", modes:["diesel"], explode:[0,1.4,-2.4], anchor:[-5.8,4.7,0],
    fr:{ name:"Groupe de refroidissement", desc:"Un moteur diesel transforme environ un tiers du gazole en travail. Le reste part en chaleur: dans l'échappement, et dans l'eau de refroidissement. Cette eau à 80 à 90 °C traverse deux radiateurs latéraux balayés par des ventilateurs de toit, qui ne démarrent qu'au-dessus d'un seuil de température." },
    en:{ name:"Cooling group", desc:"A diesel engine turns about a third of its fuel into work. The rest leaves as heat: in the exhaust, and in the coolant. Coolant at 80 to 90 °C passes through two side radiators swept by roof fans, which only start above a temperature threshold." } },
  cooling:{ cat:"aux", color:"#ff5f45", modes:["electric","tgv"], explode:[0,1.4,-2.4], anchor:[-6.2,4.7,0],
    fr:{ name:"Refroidissement", desc:"Le transformateur baigne dans l'huile et les convertisseurs chauffent: radiateurs à huile et à eau, ventilateurs de toit. Une locomotive électrique perd 5 à 10 % de sa puissance en chaleur, contre 60 à 70 % pour une diesel." },
    en:{ name:"Cooling", desc:"The transformer sits in oil and the converters run hot: oil and water radiators, roof fans. An electric locomotive loses 5 to 10% of its power as heat, versus 60 to 70% for a diesel." } },
  compressor:{ cat:"aux", color:"#cfe8ff", modes:["diesel","electric","tgv"], explode:[0,1.2,2.4], anchor:[-8.4,3.0,0],
    fr:{ name:"Compresseur d'air", desc:"Produit l'air comprimé à 8 à 10 bar stocké dans les réservoirs principaux sous le châssis. Il alimente les freins de tout le train, les sablières, le klaxon, les essuie-glaces, et sur une électrique, la levée du pantographe. Il tourne par cycles quand la pression baisse." },
    en:{ name:"Air compressor", desc:"Produces compressed air at 8 to 10 bar, stored in the main reservoirs under the frame. It feeds the brakes of the whole train, the sanders, the horn, the wipers, and on an electric locomotive, the pantograph lift. It runs in cycles as pressure drops." } },
  auxConverter:{ cat:"aux", color:"#63d2ff", modes:["electric","tgv"], explode:[0,1.2,2.4], anchor:[-0.3,4.0,0.9],
    fr:{ name:"Convertisseur auxiliaire", desc:"Fabrique, à partir du bus continu, le réseau de bord (triphasé 400 V et 74 V continu) pour le compresseur, les ventilateurs, les pompes, le chauffage de la cabine et le chargeur de batterie." },
    en:{ name:"Auxiliary converter", desc:"Makes the on-board supply (400 V three-phase and 74 V DC) from the DC link, for the compressor, fans, pumps, cab heating and the battery charger." } },
  battery:{ cat:"aux", color:"#43c977", modes:["diesel","electric","tgv"], explode:[0,-1.6,0], anchor:[3.7,0.9,1.3],
    fr:{ name:"Batterie", desc:{ diesel:"Batterie 74 V (ou 110 V) de plusieurs centaines d'ampères-heures. Tant que le moteur ne tourne pas, c'est elle qui alimente le calculateur, l'éclairage et surtout le démarreur qui lance le vilebrequin. Ensuite, un alternateur auxiliaire la recharge.", electric:"Batterie 74 V (ou 110 V). Avant la levée du pantographe, la locomotive n'a aucune autre source: elle alimente le calculateur, l'éclairage et le petit compresseur auxiliaire qui gonfle le circuit du pantographe. Ensuite, le convertisseur auxiliaire la recharge." } },
    en:{ name:"Battery", desc:{ diesel:"74 V (or 110 V) battery of several hundred amp-hours. While the engine is stopped it alone powers the computer, the lights and above all the starter that cranks the crankshaft. Once running, an auxiliary alternator recharges it.", electric:"74 V (or 110 V) battery. Before the pantograph goes up the locomotive has no other source: it powers the computer, the lights and the small auxiliary compressor that pressurises the pantograph circuit. Afterwards the auxiliary converter recharges it." } } },
  pantograph:{ cat:"power", color:"#ffd166", modes:["electric","tgv"], explode:[0,3.2,0], anchor:[2.4,5.9,0],
    fr:{ name:"Pantographe", desc:{ electric:"Bras articulé levé à l'air comprimé qui presse deux bandes de carbone contre le fil de contact avec environ 70 N. Il capte 25 000 V alternatif 50 Hz (lignes modernes françaises) ou 1 500 V continu (réseau historique). Le courant traverse toute la locomotive et revient à la sous-station par les roues et les rails.", tgv:"Sur un TGV sous 25 kV, un seul pantographe par rame est levé, celui de la motrice arrière: le fil de contact, soulevé par un premier passage, devient instable pour un second. Celui de la motrice de tête reste plié; elle reçoit son courant par la ligne de toiture. Bandes de carbone pressées à 70 N sur un fil qui défile à 320 km/h: le point le plus délicat de la rame. Sous 1 500 V continu, les deux motrices lèvent le leur: environ 2 450 A par rame, trop pour un seul pantographe." } },
    en:{ name:"Pantograph", desc:{ electric:"An articulated arm raised by compressed air, pressing two carbon strips against the contact wire with about 70 N. It collects 25,000 V AC 50 Hz (modern French lines) or 1,500 V DC (the older network). Current flows through the whole locomotive and returns to the substation through the wheels and the rails.", tgv:"On a TGV under 25 kV a single pantograph per set is raised, the rear power car's: the contact wire, lifted by a first pass, becomes unstable for a second one. The leading power car's stays folded; it gets its current through the roof line. Carbon strips pressed at 70 N against a wire passing at 320 km/h: the most delicate point of the whole set. Under 1,500 V DC both power cars raise theirs: about 2,450 A per set, too much for a single pantograph." } } },
  vcb:{ cat:"power", color:"#ffd166", modes:["electric","tgv"], explode:[0,3.2,0], anchor:[4.6,5.4,0],
    fr:{ name:"Disjoncteur principal", desc:"Interrupteur haute tension sur le toit (à vide ou au SF6). Il relie la locomotive à la caténaire une fois le pantographe levé, et l'isole en quelques millisecondes en cas de défaut. Rien en dessous n'est sous tension tant qu'il est ouvert." },
    en:{ name:"Main circuit breaker", desc:"High-voltage switch on the roof (vacuum or SF6). It connects the locomotive to the overhead line once the pantograph is up, and isolates it within milliseconds if a fault appears. Nothing below it is live while it is open." } },
  transformer:{ cat:"power", color:"#c77b3a", modes:["electric","tgv"], explode:[0,-2.2,0], anchor:[0,0.45,1.3],
    fr:{ name:"Transformateur principal", desc:"Sous le châssis, 8 à 12 tonnes refroidies à l'huile. Son primaire reçoit 25 000 V; ses secondaires fournissent 1 000 à 1 800 V aux convertisseurs de traction et aux auxiliaires. Il ne fonctionne qu'en alternatif: sous 1 500 V continu, il est contourné et les convertisseurs prennent la ligne en direct." },
    en:{ name:"Main transformer", desc:"Under the frame, 8 to 12 tonnes, oil cooled. Its primary takes 25,000 V; its secondaries deliver 1,000 to 1,800 V to the traction converters and auxiliaries. It only works on AC: under 1,500 V DC it is bypassed and the converters take the line directly." } },
  catenary:{ cat:"struct", color:"#c9a27c", modes:["electric","tgv"], explode:[0,0,0], anchor:[-8,6.6,0],
    fr:{ name:"Caténaire et rails", desc:"Fil de contact en cuivre tendu à 5,1 à 5,4 m au-dessus des rails, porté par un câble porteur. Alimenté par une sous-station tous les 40 à 60 km. Les rails font office de conducteur de retour, avec des câbles de terre le long de la voie. Une seule sous-station peut alimenter plusieurs trains à la fois. Le fil zigzague de ±20 cm d'un poteau à l'autre pour user uniformément la bande de frottement du pantographe. Sous 1 500 V continu, le courant est bien plus fort: deux fils de contact et une sous-station tous les 10 à 20 km." },
    en:{ name:"Overhead line and rails", desc:"A copper contact wire strung 5.1 to 5.4 m above the rails, held by a messenger wire. Fed by a substation every 40 to 60 km. The rails act as the return conductor, with earth cables along the track. One substation can feed several trains at once. The wire zigzags ±20 cm from mast to mast so the pantograph's carbon strip wears evenly. Under 1,500 V DC the current is much higher: two contact wires and a substation every 10 to 20 km." } },
  cab:{ cat:"struct", color:"#8e9ca9", modes:["diesel","electric","tgv"], explode:[3.0,0.8,0], anchor:[8.2,3.4,0],
    fr:{ name:"Poste de conduite", desc:"La manette de traction (8 crans sur une diesel américaine, continue sur une électrique européenne) ne commande rien directement: elle donne une consigne d'effort au calculateur. Le conducteur dispose aussi du frein électrique, du frein pneumatique du train, du frein direct de la locomotive, de la vigilance et des écrans de diagnostic. Ici le cran est une consigne de vitesse: 8 = la vitesse maximale du train (320 km/h en TGV), 4 = la moitié. En conduite manuelle la limite de la ligne n'est pas imposée; l'arrêt en gare et le guide, eux, la respectent. Le régulateur réduit l'effort à l'approche de la consigne." },
    en:{ name:"Driver's cab", desc:"The throttle (8 notches on an American diesel, continuous on a European electric) controls nothing directly: it sends an effort demand to the computer. The driver also has the electric brake, the train air brake, the locomotive's independent brake, the vigilance device and diagnostic screens. Here the notch is a speed target: 8 = the train's maximum speed (320 km/h for the TGV), 4 = half of it. Manual driving ignores the line limit; the station stop and the guide respect it. The regulator eases the effort off as the train gets there." } },
  frame:{ cat:"struct", color:"#4a545e", modes:["diesel","electric","tgv"], explode:[0,0,0], anchor:[9.6,1.9,0],
    fr:{ name:"Châssis", desc:"Poutre-caisson en acier soudé qui porte tout: 80 à 130 tonnes au total, réparties sur les 4 essieux (20 à 22,5 t par essieu, la limite du réseau). Les attelages et tampons aux extrémités transmettent l'effort au train." },
    en:{ name:"Underframe", desc:"A welded steel box girder that carries everything: 80 to 130 tonnes in all, spread over the 4 axles (20 to 22.5 t per axle, the network limit). The couplers and buffers at each end pass the effort to the train." } },
  shell:{ cat:"struct", color:"#2f5f9e", modes:["diesel","electric"], explode:[0,5.0,0], anchor:[-2,4.6,0],
    fr:{ name:"Carrosserie", desc:"Caisse en tôle d'acier: elle protège la salle des machines et canalise l'air de refroidissement par ses persiennes. Elle porte peu de charge; le châssis fait le travail. Rendez-la transparente ou masquez-la dans l'onglet Vues pour voir l'intérieur." },
    en:{ name:"Body shell", desc:"Steel sheet body: it shelters the machine room and channels cooling air through its louvres. It carries little load; the underframe does the work. Make it see-through or hide it in the Views tab to look inside." } },
  tgvShell:{ cat:"struct", color:"#b7bcc2", modes:["tgv"], explode:[0,5.0,0], anchor:[-2,4.6,0],
    fr:{ name:"Caisse de la motrice", desc:"Motrice TGV Duplex: 22 m, 68 t, nez profilé pour 320 km/h, livrée TGV inOui. Elle ne transporte aucun voyageur: tout le volume est pris par le transformateur, les convertisseurs et le refroidissement. Rendez-la transparente ou masquez-la dans l'onglet Vues pour voir l'intérieur." },
    en:{ name:"Power car body", desc:"TGV Duplex power car: 22 m, 68 t, nose shaped for 320 km/h, TGV inOui livery. It carries no passengers: the whole volume is taken by the transformer, converters and cooling. Make it see-through or hide it in the Views tab to look inside." } },
  powerCars:{ cat:"power", color:"#c8435f", modes:["tgv"], explode:[0,0,0], anchor:[-174,4.6,0],
    fr:{ name:"Motrice arrière", desc:"Chaque rame a deux motrices identiques, une à chaque bout, 4 400 kW chacune: 8 800 kW par rame, 17 600 kW en unité multiple. Celle de queue pousse pendant que celle de tête tire, toutes deux commandées depuis la cabine de tête par les câbles de télécommande. Sous 25 kV, c'est elle qui lève le pantographe; la motrice de tête est alimentée par la ligne de toiture. Sous 1 500 V continu, chacune lève son propre pantographe et la rame ne donne plus que 3 680 kW." },
    en:{ name:"Rear power car", desc:"Each set has two identical power cars, one at each end, 4,400 kW each: 8,800 kW per set, 17,600 kW as a double set. The rear one pushes while the front one pulls, both driven from the leading cab through the remote-control cables. Under 25 kV it is the one raising the pantograph; the leading power car is fed through the roof line. Under 1,500 V DC each raises its own pantograph and the set gives only 3,680 kW." } },
  roofLine:{ cat:"power", color:"#ffb347", modes:["tgv"], explode:[0,0,0], anchor:[-60,4.9,0],
    fr:{ name:"Ligne de toiture 25 kV", desc:"Sous 25 kV, une seule motrice par rame lève son pantographe, celle de l'arrière: le fil de contact souffre moins. Le courant traverse alors toute la rame par ce câble haute tension posé sur le toit des remorques, d'isolateur en isolateur, jusqu'au disjoncteur de la motrice de tête. En unité multiple, la ligne s'arrête à l'attelage: deux pantographes levés pour deux rames. Sous 1 500 V continu, elle reste hors tension: chaque motrice lève son propre pantographe." },
    en:{ name:"25 kV roof line", desc:"Under 25 kV only one power car per set raises its pantograph, the rear one: the contact wire suffers less. The current then crosses the whole set through this high-voltage cable laid on the trailer roofs, insulator after insulator, down to the leading power car's breaker. In a double set the line stops at the coupling: two pantographs up for two sets. Under 1,500 V DC it stays dead: each power car raises its own pantograph." } },
  trailers:{ cat:"struct", color:"#8fa3b8", modes:["tgv"], explode:[0,0,0], anchor:[-40,4.6,0],
    fr:{ name:"Remorques Duplex (×8)", desc:"Huit remorques à deux niveaux, 18,7 m chacune, 510 places par rame. Elles sont articulées: deux voisines reposent sur le même bogie, si bien que la rame ne se disloque pas en cas de déraillement et qu'aucun bogie ne roule sous les voyageurs, donc moins de bruit. Aucun moteur: toute la traction vient des deux motrices." },
    en:{ name:"Duplex trailers (×8)", desc:"Eight double-deck trailers, 18.7 m each, 510 seats per set. They are articulated: two neighbours rest on the same bogie, so the set does not break apart in a derailment and no bogie runs under the passengers, hence less noise. No motors: all traction comes from the two power cars." } },
  jacobs:{ cat:"traction", color:"#5a6068", modes:["tgv"], explode:[0,0,0], anchor:[-31,1.2,1.4],
    fr:{ name:"Bogies Jacobs (×7)", desc:"Un bogie porteur partagé entre deux remorques, sous l'intercirculation. 13 bogies pour 10 véhicules au lieu de 20: moins de masse, moins de résistance, et une rame qui reste dans l'axe à 320 km/h. Ils portent les disques de frein qui, avec le frein électrique des motrices, arrêtent 380 tonnes lancées à 320 km/h en 3,3 km." },
    en:{ name:"Jacobs bogies (×7)", desc:"A carrying bogie shared by two trailers, under the gangway. 13 bogies for 10 vehicles instead of 20: less mass, less drag, and a set that stays in line at 320 km/h. They carry the disc brakes which, together with the power cars' electric brake, stop 380 tonnes from 320 km/h in 3.3 km." } },
  doors:{ cat:"aux", color:"#63d2ff", modes:["tgv"], explode:[0,0,0], anchor:[-29,2.2,1.7],
    fr:{ name:"Portes louvoyantes", desc:"Une porte par face et par remorque, au niveau bas, 1,3 m de large. À l'ouverture, elle se décolle d'abord de la caisse (louvoyante) puis coulisse le long du flanc: la caisse reste lisse à 320 km/h. Le calculateur ne les déverrouille qu'à l'arrêt, du côté du quai, et interdit toute traction tant qu'une porte est ouverte. Les voyageurs descendent, puis montent; fermeture et verrouillage avant le départ." },
    en:{ name:"Plug-sliding doors", desc:"One door per side per trailer, on the lower deck, 1.3 m wide. To open, it first moves out from the body (plug door) then slides along the side: the body stays smooth at 320 km/h. The computer only unlocks them at standstill, on the platform side, and inhibits traction while any door is open. Passengers step off, then on; the doors close and lock before departure." } },
  coupler:{ cat:"struct", color:"#f2c53d", modes:["tgv"], explode:[3,0,0], anchor:[11.3,1.3,0],
    fr:{ name:"Attelage Scharfenberg", desc:"Derrière la trappe du nez, un attelage automatique. En accostant à 2 km/h, les deux têtes se verrouillent et raccordent en même temps la conduite de frein et les câbles de commande. Deux rames ainsi couplées forment une unité multiple (UM) de 400 m, conduite depuis la cabine de tête. Le 25 kV, lui, ne traverse pas l'attelage: chaque rame lève son propre pantographe." },
    en:{ name:"Scharfenberg coupler", desc:"Behind the nose hatch, an automatic coupler. Nosing in at 2 km/h, the two heads lock and connect the brake pipe and the control cables at the same time. Two sets coupled this way form a 400 m double set (UM), driven from the leading cab. The 25 kV itself does not cross the coupling: each set raises its own pantograph." } },
};
const CAT_ORDER = ["power","conv","traction","aux","struct"];

/* --------------------------------------------------------------- steps */
const STEPS = {
  diesel: [
    { id:"d0", cam:"overview", focus:null, dur:9,
      fr:{ t:"La chaîne de traction", x:"Gazole → moteur diesel → alternateur → redresseur → onduleurs → moteurs de traction → engrenages → roues. Le moteur diesel n'entraîne jamais les roues: il produit de l'électricité, et ce sont des moteurs électriques qui tirent le train. Tout est éteint. Suivez les étapes, ou prenez les commandes." },
      en:{ t:"The traction chain", x:"Fuel → diesel engine → alternator → rectifier → inverters → traction motors → gears → wheels. The diesel engine never drives the wheels: it makes electricity, and electric motors pull the train. Everything is off. Follow the steps, or take the controls." } },
    { id:"d1", cam:"battery", focus:"battery", dur:7,
      fr:{ t:"Coupe-batterie", x:"Le conducteur ferme le coupe-batterie. 74 V continu alimentent le calculateur, les écrans, l'éclairage et les feux. Rien ne bouge encore: la locomotive est réveillée, pas allumée." },
      en:{ t:"Battery switch", x:"The driver closes the battery switch. 74 V DC powers the computer, the screens, the lighting and the headlights. Nothing moves yet: the locomotive is awake, not on." } },
    { id:"d2", cam:"engine", focus:"engine", dur:9,
      fr:{ t:"Lancement du moteur", x:"Le démarreur (ou l'alternateur principal utilisé en moteur) lance le vilebrequin à une centaine de tours par minute. Injection de gazole, compression, allumage: le moteur prend et monte à son ralenti, 300 tr/min. Le turbo commence à tourner, poussé par l'échappement. Fumée noire quelques secondes." },
      en:{ t:"Cranking the engine", x:"The starter (or the main alternator run as a motor) spins the crankshaft to about a hundred rpm. Fuel injection, compression, ignition: the engine catches and climbs to idle, 300 rpm. The turbo starts spinning, pushed by the exhaust. Black smoke for a few seconds." } },
    { id:"d3", cam:"alternator", focus:"alternator", dur:9,
      fr:{ t:"Ralenti: tourner pour rien", x:"Le moteur tourne, l'alternateur aussi, mais sans excitation il ne débite aucun courant. Le compresseur charge les réservoirs d'air pour les freins. La pompe fait circuler l'eau de refroidissement. La locomotive consomme 10 à 20 L/h juste pour attendre." },
      en:{ t:"Idle: spinning for nothing", x:"The engine runs and so does the alternator, but with no excitation it delivers no current. The compressor charges the air reservoirs for the brakes. The pump circulates the coolant. The locomotive burns 10 to 20 L/h just to wait." } },
    { id:"d4", cam:"bogie", focus:"motors", dur:11,
      fr:{ t:"Cran 1: le train démarre", x:"La manette passe au cran 1. Le calculateur monte le régime et excite l'alternateur: du courant alternatif sort, le redresseur le lisse en continu, les onduleurs fabriquent un triphasé à très basse fréquence, et les quatre moteurs poussent les roues avec un couple énorme mais lentement. Le train s'ébranle." },
      en:{ t:"Notch 1: the train moves", x:"The throttle goes to notch 1. The computer raises engine speed and excites the alternator: AC comes out, the rectifier smooths it to DC, the inverters make a very low-frequency three-phase supply, and the four motors push the wheels with huge torque, slowly. The train starts rolling." } },
    { id:"d5", cam:"side", focus:"radiator", dur:12,
      fr:{ t:"Cran 8: pleine puissance", x:"900 tr/min, 3 300 kW, plus de 2 000 A dans les câbles. Un tiers du gazole devient de la force à la jante; le reste part en chaleur: les ventilateurs de toit tournent dès que l'eau dépasse 80 °C. La vitesse monte, l'effort baisse: à puissance constante, effort × vitesse = constante." },
      en:{ t:"Notch 8: full power", x:"900 rpm, 3,300 kW, over 2,000 A in the cables. A third of the fuel becomes force at the rail; the rest leaves as heat: the roof fans run as soon as the coolant passes 80 °C. Speed climbs, effort falls: at constant power, effort × speed stays constant." } },
    { id:"d6", cam:"grids", focus:"brakeGrids", dur:12,
      fr:{ t:"Freinage électrique", x:"Manette à zéro, levier de frein électrique: les onduleurs inversent le jeu et les moteurs, entraînés par les roues, deviennent des générateurs. Leur courant chauffe les grilles du toit au rouge, refroidies par ventilateur. Le train ralentit sans toucher aux sabots. Le diesel remonte un peu de régime pour alimenter les ventilateurs." },
      en:{ t:"Electric braking", x:"Throttle to zero, dynamic brake lever on: the inverters reverse the game and the motors, driven by the wheels, become generators. Their current heats the roof grids red hot, cooled by a fan. The train slows without touching the brake shoes. The diesel speeds up a little to power the blowers." } },
    { id:"d7", cam:"engine", focus:"engine", dur:12,
      fr:{ t:"Arrêt du moteur", x:"Train immobilisé, frein à air serré. Le conducteur coupe l'injection: le vilebrequin s'arrête en une dizaine de secondes, le turbo siffle en décélérant, les ventilateurs s'arrêtent. Puis il ouvre le coupe-batterie: la locomotive est froide. Sur un dépôt, on la laisse souvent au ralenti l'hiver pour éviter le gel." },
      en:{ t:"Shutting down", x:"Train stopped, air brake applied. The driver cuts the injection: the crankshaft stops within ten seconds, the turbo whines down, the fans stop. Then the battery switch opens: the locomotive is cold. In winter yards it is often left idling to keep the coolant from freezing." } },
  ],
  electric: [
    { id:"e0", cam:"overview", focus:null, dur:9,
      fr:{ t:"La chaîne de traction", x:"Caténaire → pantographe → disjoncteur → transformateur → convertisseur 4 quadrants → bus continu → onduleurs → moteurs → engrenages → roues. Même bogie, mêmes moteurs, mêmes onduleurs qu'une diesel-électrique: seule la source change. La centrale n'est plus à bord, elle est à 50 km." },
      en:{ t:"The traction chain", x:"Overhead line → pantograph → circuit breaker → transformer → four-quadrant converter → DC link → inverters → motors → gears → wheels. Same bogie, same motors, same inverters as a diesel-electric: only the source changes. The power plant is no longer on board, it is 50 km away." } },
    { id:"e1", cam:"battery", focus:"battery", dur:7,
      fr:{ t:"Coupe-batterie", x:"74 V continu réveillent le calculateur, les écrans et les feux. Un petit compresseur auxiliaire sur batterie gonfle le circuit d'air du pantographe. Sans caténaire, la locomotive ne peut rien faire d'autre." },
      en:{ t:"Battery switch", x:"74 V DC wakes the computer, the screens and the headlights. A small battery-powered auxiliary compressor pressurises the pantograph's air circuit. Without the overhead line the locomotive can do nothing else." } },
    { id:"e2", cam:"roof", focus:"pantograph", dur:9,
      fr:{ t:"Levée du pantographe", x:"L'air comprimé déplie le bras en 6 à 10 secondes. Les bandes de carbone touchent le fil de contact: 25 000 V sont présents sur le toit, mais le disjoncteur est ouvert, rien ne circule encore." },
      en:{ t:"Raising the pantograph", x:"Compressed air unfolds the arm in 6 to 10 seconds. The carbon strips touch the contact wire: 25,000 V is now on the roof, but the breaker is open and nothing flows yet." },
      dc:{ fr:{ t:"Levée du pantographe", x:"L'air comprimé déplie le bras en 6 à 10 secondes. Les bandes de carbone touchent le fil de contact: 1 500 V continu sont présents sur le toit (ici, le réseau historique), mais le disjoncteur est ouvert, rien ne circule encore." },
        en:{ t:"Raising the pantograph", x:"Compressed air unfolds the arm in 6 to 10 seconds. The carbon strips touch the contact wire: 1,500 V DC is now on the roof (the older network here), but the breaker is open and nothing flows yet." } } },
    { id:"e3", cam:"under", focus:"transformer", dur:10,
      fr:{ t:"Fermeture du disjoncteur", x:"Clac. Le transformateur est sous tension: 25 000 V au primaire, 1 500 V aux secondaires. Les convertisseurs 4 quadrants chargent le bus continu à 2 800 V. Le convertisseur auxiliaire prend le relais de la batterie: compresseur et ventilateurs démarrent. La locomotive est prête." },
      en:{ t:"Closing the breaker", x:"Clack. The transformer is live: 25,000 V on the primary, 1,500 V on the secondaries. The four-quadrant converters charge the DC link to 2,800 V. The auxiliary converter takes over from the battery: compressor and fans start. The locomotive is ready." },
      dc:{ cam:"side", focus:"converter4q",
        fr:{ t:"Fermeture du disjoncteur", x:"Clac. Sous 1 500 V continu, le transformateur est contourné: le courant de la ligne passe par une inductance de filtrage et arrive directement sur le bus continu, à 1 500 V. Le convertisseur auxiliaire prend le relais de la batterie: compresseur et ventilateurs démarrent. La locomotive est prête." },
        en:{ t:"Closing the breaker", x:"Clack. Under 1,500 V DC the transformer is bypassed: line current goes through a filter inductor straight onto the DC link, at 1,500 V. The auxiliary converter takes over from the battery: compressor and fans start. The locomotive is ready." } } },
    { id:"e4", cam:"bogie", focus:"motors", dur:11,
      fr:{ t:"Traction: le train démarre", x:"Le conducteur demande de l'effort. Les onduleurs envoient un triphasé à basse fréquence aux moteurs, qui poussent les roues. Le courant traverse toute la chaîne depuis la caténaire et revient à la sous-station par les roues et les rails: le circuit est bouclé par la voie elle-même." },
      en:{ t:"Traction: the train moves", x:"The driver asks for effort. The inverters send low-frequency three-phase power to the motors, which push the wheels. Current flows through the whole chain from the overhead line and returns to the substation through the wheels and rails: the circuit is closed by the track itself." } },
    { id:"e5", cam:"side", focus:"converter4q", dur:12,
      fr:{ t:"Pleine puissance", x:"5 600 kW, sans moteur thermique, sans montée en régime, sans fumée: la puissance est disponible instantanément et le rendement dépasse 90 %. Une électrique de 90 t tire autant qu'une diesel de 130 t. Sa limite, c'est l'adhérence roue-rail, pas la source." },
      en:{ t:"Full power", x:"5,600 kW, with no heat engine, no spool-up, no smoke: power is available instantly and efficiency exceeds 90%. A 90 t electric pulls as much as a 130 t diesel. Its limit is wheel-rail adhesion, not the source." } },
    { id:"e6", cam:"roof", focus:"pantograph", dur:12,
      fr:{ t:"Freinage à récupération", x:"Les moteurs deviennent générateurs. Le convertisseur 4 quadrants renvoie leur courant vers le transformateur puis la caténaire, où un autre train l'utilise. Si la ligne n'est pas réceptive, les résistances de toit prennent le surplus. Un TGV récupère ainsi 10 à 15 % de son énergie." },
      en:{ t:"Regenerative braking", x:"The motors become generators. The four-quadrant converter pushes their current back through the transformer into the overhead line, where another train uses it. If the line is not receptive, the roof resistors take the surplus. A high-speed train recovers 10 to 15% of its energy this way." },
      dc:{ fr:{ t:"Freinage à récupération", x:"Les moteurs deviennent générateurs. Sous 1 500 V continu, le courant repart directement dans la caténaire, sans passer par le transformateur, à condition qu'un autre train soit là pour le consommer: les sous-stations continues ne savent pas le renvoyer au réseau. Sinon, les résistances de toit prennent le surplus." },
        en:{ t:"Regenerative braking", x:"The motors become generators. Under 1,500 V DC their current goes straight back into the overhead line, without the transformer, as long as another train nearby can use it: DC substations cannot send it back to the grid. Otherwise the roof resistors take the surplus." } } },
    { id:"e7", cam:"roof", focus:"vcb", dur:12,
      fr:{ t:"Mise hors tension", x:"Train arrêté. Le disjoncteur s'ouvre: le bus continu se décharge, les ventilateurs s'arrêtent. Le pantographe descend. Coupe-batterie ouvert: la locomotive est froide. Elle peut redémarrer en moins d'une minute." },
      en:{ t:"Powering down", x:"Train stopped. The breaker opens: the DC link discharges, the fans stop. The pantograph comes down. Battery switch open: the locomotive is cold. It can restart in under a minute." } },
  ],
  tgv: [
    { id:"t0", cam:"train", focus:null, dur:10,
      fr:{ t:"Un TGV Duplex", x:"Deux motrices encadrent huit remorques articulées à deux niveaux: 200 m, 380 t, 8 800 kW, 320 km/h. Même chaîne qu'une locomotive électrique (caténaire → pantographe → disjoncteur → transformateur → convertisseurs → onduleurs → moteurs), mais répartie sur deux motrices reliées par une ligne de toiture. Deux rames accouplées font un double TGV de 400 m." },
      en:{ t:"A TGV Duplex set", x:"Two power cars frame eight articulated double-deck trailers: 200 m, 380 t, 8,800 kW, 320 km/h. Same chain as an electric locomotive (overhead line → pantograph → breaker → transformer → converters → inverters → motors), but split over two power cars linked by a roof line. Two sets coupled together make a 400 m double TGV." } },
    { id:"t1", cam:"battery", focus:"battery", dur:7,
      fr:{ t:"Coupe-batterie", x:"Le conducteur réveille la rame depuis la cabine de tête: 72 V continu pour les calculateurs des deux motrices, les écrans, les feux et l'air du pantographe. Les huit remorques restent éteintes jusqu'à ce que la caténaire alimente la rame." },
      en:{ t:"Battery switch", x:"The driver wakes the set from the leading cab: 72 V DC for both power cars' computers, the screens, the headlights and the pantograph air. The eight trailers stay dark until the overhead line powers the set." } },
    { id:"t2", cam:"rearroof", focus:"roofLine", dur:10,
      fr:{ t:"Pantographe arrière levé", x:"Sous 25 kV, c'est le pantographe de la motrice de queue qui monte, 200 m derrière le conducteur. Le 25 000 V arrive sur le toit arrière et file vers l'avant par la ligne de toiture, au-dessus des remorques, jusqu'au disjoncteur de la motrice de tête. Celui de tête reste plié: il perturberait le fil pour celui de derrière." },
      en:{ t:"Rear pantograph up", x:"Under 25 kV the rear power car's pantograph rises, 200 m behind the driver. 25,000 V reaches the rear roof and runs forward through the roof line, above the trailers, to the leading power car's breaker. The front one stays folded: it would disturb the wire for the one behind." },
      dc:{ cam:"roof", focus:"pantograph",
        fr:{ t:"Deux pantographes levés", x:"Sur le réseau historique en 1 500 V continu (Toulouse, Agen, Bordeaux, Angoulême, Poitiers, Tours, l'entrée de Paris), les deux motrices lèvent leur pantographe: une rame appelle environ 2 450 A, sept fois plus qu'en 25 kV, trop pour la ligne de toiture et pour un seul pantographe. Chaque motrice prend donc son courant directement au fil. Le 25 kV commence sur la ligne à grande vitesse." },
        en:{ t:"Both pantographs up", x:"On the older 1,500 V DC network (Toulouse, Agen, Bordeaux, Angoulême, Poitiers, Tours, the way into Paris) both power cars raise their pantograph: a set draws about 2,450 A, seven times more than under 25 kV, too much for the roof line and for a single pantograph. Each power car takes its own current from the wire. 25 kV starts on the high-speed line." } } },
    { id:"t3", cam:"under", focus:"transformer", dur:10,
      fr:{ t:"Disjoncteurs fermés", x:"Les deux disjoncteurs se ferment ensemble. Chaque motrice met son transformateur sous tension, charge son bus continu à 2 800 V et lance ses auxiliaires: compresseurs, ventilateurs, et pour la première fois la climatisation et l'éclairage des remorques via la ligne de train." },
      en:{ t:"Breakers closed", x:"Both breakers close together. Each power car energises its transformer, charges its DC link to 2,800 V and starts its auxiliaries: compressors, fans, and for the first time the trailers' air conditioning and lighting through the train line." },
      dc:{ cam:"side", focus:"converter4q",
        fr:{ t:"Disjoncteurs fermés", x:"Les deux disjoncteurs se ferment ensemble. Sous 1 500 V continu, chaque motrice contourne son transformateur: le courant de son propre pantographe passe par un filtre et charge directement son bus continu. Les auxiliaires démarrent: compresseurs, ventilateurs, et pour la première fois la climatisation et l'éclairage des remorques via la ligne de train." },
        en:{ t:"Breakers closed", x:"Both breakers close together. Under 1,500 V DC each power car bypasses its transformer: current from its own pantograph goes through a filter straight onto its DC link. The auxiliaries start: compressors, fans, and for the first time the trailers' air conditioning and lighting through the train line." } } },
    { id:"t4", cam:"bogie", focus:"motors", dur:11,
      fr:{ t:"Départ: 8 moteurs", x:"Le conducteur demande de l'effort: la motrice de tête tire, celle de queue pousse, 8 moteurs asynchrones de 1 100 kW. Effort au démarrage limité par l'adhérence à 220 kN pour 380 t: le TGV démarre doucement, comme une locomotive, mais n'arrête plus d'accélérer." },
      en:{ t:"Departure: 8 motors", x:"The driver asks for effort: the leading power car pulls, the rear one pushes, 8 induction motors of 1,100 kW. Starting effort limited by adhesion to 220 kN for 380 t: the TGV starts gently, like a locomotive, and then never stops accelerating." } },
    { id:"t5", cam:"side", focus:"converter4q", dur:12,
      fr:{ t:"320 km/h", x:"À 320 km/h, 90 % de la puissance sert à vaincre l'air: d'où le nez profilé, la caisse lisse, les intercirculations carénées. 8 800 kW sous 25 kV, soit 350 A dans le fil de contact. Le pantographe suit un fil qui défile à 90 m/s: c'est lui, pas les moteurs, qui limite la vitesse." },
      en:{ t:"320 km/h", x:"At 320 km/h, 90% of the power fights the air: hence the shaped nose, the smooth body, the faired gangways. 8,800 kW under 25 kV, that is 350 A in the contact wire. The pantograph follows a wire passing at 90 m/s: it, not the motors, sets the speed limit." } },
    { id:"t6", cam:"station", focus:"doors", dur:36,
      fr:{ t:"Arrêt en gare", x:"Freinage 3 km avant le quai: frein électrique des motrices d'abord (l'énergie repart dans la caténaire), disques des remorques ensuite. Objectif: le repère d'arrêt de la composition, pour que chaque voiture tombe devant sa lettre de quai. À l'arrêt, déverrouillage des portes côté quai: elles se décollent puis coulissent, les voyageurs descendent, puis montent." },
      en:{ t:"Station stop", x:"Braking starts 3 km before the platform: the power cars' electric brake first (the energy goes back into the overhead line), then the trailers' disc brakes. The aim is the stopping mark for this formation, so that each car lines up with its platform letter. Once stopped, the platform-side doors unlock: they move out then slide, passengers step off, then on." } },
    { id:"t7", cam:"coupler", focus:"coupler", dur:24,
      fr:{ t:"Accouplement en UM", x:"Une seconde rame accoste à 2 km/h par l'arrière. Trappes de nez ouvertes, les attelages Scharfenberg se verrouillent et raccordent freins et télécommande en un seul geste. Le double TGV fait 400 m, 4 motrices, 17 600 kW, 1 020 places: le quai est prévu pour lui. Chaque rame garde son propre pantographe levé." },
      en:{ t:"Coupling into a double set", x:"A second set noses in at 2 km/h from behind. Nose hatches open, the Scharfenberg couplers lock and connect brakes and remote control in one move. The double TGV is 400 m long, 4 power cars, 17,600 kW, 1,020 seats: the platform is built for it. Each set keeps its own pantograph up." },
      dc:{ fr:{ t:"Accouplement en UM", x:"Une seconde rame accoste à 2 km/h par l'arrière. Trappes de nez ouvertes, les attelages Scharfenberg se verrouillent et raccordent freins et télécommande en un seul geste. Le double TGV fait 400 m, 4 motrices, 1 020 places: le quai est prévu pour lui. Sous 1 500 V continu, les quatre motrices gardent chacune leur pantographe levé: 7 360 kW en tout." },
        en:{ t:"Coupling into a double set", x:"A second set noses in at 2 km/h from behind. Nose hatches open, the Scharfenberg couplers lock and connect brakes and remote control in one move. The double TGV is 400 m long, 4 power cars, 1,020 seats: the platform is built for it. Under 1,500 V DC all four power cars keep their own pantograph up: 7,360 kW in all." } } },
    { id:"t8", cam:"train", focus:null, dur:14,
      fr:{ t:"Départ en unité multiple", x:"Portes fermées et verrouillées, le calculateur autorise la traction. Le conducteur de tête commande les 4 motrices: 16 moteurs, deux fois plus de puissance pour deux fois plus de masse, donc la même accélération. À 320 km/h, un double TGV consomme à peine plus que deux rames seules: l'air n'est fendu qu'une fois." },
      en:{ t:"Departing as a double set", x:"Doors closed and locked, the computer allows traction. The leading driver controls all 4 power cars: 16 motors, twice the power for twice the mass, hence the same acceleration. At 320 km/h a double TGV uses barely more than two single sets: the air is split only once." } },
  ]
};
